function Huella([string]$ruta) {
    # Misma huella en Windows y Linux: se ignoran los saltos de línea (CRLF/LF), la marca BOM,
    # los espacios al final de cada línea y las líneas vacías del final (NetBeans a veces los cambia al guardar)
    $lineas = [System.IO.File]::ReadAllText($ruta, [System.Text.Encoding]::UTF8).Replace("`r`n", "`n").Split("`n")
    $texto = (($lineas | ForEach-Object { $_.TrimEnd() }) -join "`n").TrimEnd()
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($texto)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    return ([System.BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-', '').ToLower()
}

$faltan = @(); $viejos = @()
foreach ($rel in $esperados.Keys) {
    $ruta = Join-Path $raiz ($rel -replace '/', '\')
    if (-not (Test-Path -LiteralPath $ruta)) { $faltan += $rel; continue }
    if ((Huella $ruta) -ne $esperados[$rel]) { $viejos += $rel }
}
$sobran = @()
$srcJava = Join-Path $raiz 'src\java'
if (Test-Path $srcJava) {
    Get-ChildItem -Path $srcJava -Recurse -Filter *.java | ForEach-Object {
        $rel = ($_.FullName.Substring($raiz.Length + 1)) -replace '\\', '/'
        if (-not $esperados.Contains($rel)) { $sobran += $rel }
    }
}

Write-Host ""
Write-Host "ClinicaWeb - verificación de la Etapa 7 (citas)" -ForegroundColor Cyan
Write-Host ("Proyecto: " + $raiz)
Write-Host ("Archivos revisados: " + $esperados.Count)
Write-Host ""
if ($faltan.Count -gt 0) {
    Write-Host ("FALTAN " + $faltan.Count + " archivos (cópialos del zip a la misma carpeta):") -ForegroundColor Red
    $faltan | ForEach-Object { Write-Host ("   " + $_) -ForegroundColor Red }
    Write-Host ""
}
if ($viejos.Count -gt 0) {
    Write-Host ("DESACTUALIZADOS " + $viejos.Count + " archivos (existen, pero son de otra versión: reemplázalos con los del zip):") -ForegroundColor Yellow
    $viejos | ForEach-Object { Write-Host ("   " + $_) -ForegroundColor Yellow }
    Write-Host ""
}
if ($sobran.Count -gt 0) {
    Write-Host ("SOBRAN " + $sobran.Count + " archivos .java que no son de esta versión:") -ForegroundColor Magenta
    $sobran | ForEach-Object { Write-Host ("   " + $_) -ForegroundColor Magenta }
    Write-Host "   Si son copias viejas (por ejemplo, en un paquete 'administracion'), bórralas: dos controladores" -ForegroundColor Magenta
    Write-Host "   con la misma dirección (@WebServlet) impiden que Tomcat arranque. Si son tuyos a propósito, déjalos." -ForegroundColor Magenta
    Write-Host ""
}
if ($faltan.Count -eq 0 -and $viejos.Count -eq 0) {
    Write-Host "Todo completo y al día. Ahora: Clean and Build y Run." -ForegroundColor Green
}

